import subprocess
branches=['friend/rachel','friend/monica','friend/phoebe','friend/joey','friend/chandler','friend/ross']
from collections import Counter
c=Counter()
for b in branches:
    out=subprocess.check_output(['git','log','--format=%B%x1e',f'origin/{b}'], text=True)
    for commit in out.split('\x1e'):
        ep=None; fm=None
        for line in commit.splitlines():
            if line.startswith('Episode:'): ep=line.split(':',1)[1].strip()
            if line.startswith('Friend-Message:'): fm=line.strip()
        if fm=='Friend-Message: 1' and ep:
            c[ep]+=1
print(c)
